  "үлкен": { ru: "большая", en: "high" },
  "№1 — оқыту үшін жапсырма керек": { ru: "№1 — для обучения нужны метки", en: "No. 1 — labels needed for training" },
  "Батыс Қазақстан WNV / Culex modestus, Frontiers in Public Health (2020)": { ru: "Западный Казахстан WNV / Culex modestus, Frontiers in Public Health (2020)", en: "Western Kazakhstan WNV / Culex modestus, Frontiers in Public Health (2020)" },
  "WNV Қазақстан жылқыларында, Атырауды қоса (8,7 %)": { ru: "WNV у лошадей Казахстана, включая Атырау (8,7 %)", en: "WNV in Kazakhstan horses, including Atyrau (8.7%)" },
  "MAMOTH — Earth Observation data-driven model for mosquito abundance; EYWA жүйесі": { ru: "MAMOTH — Earth Observation data-driven model for mosquito abundance; система EYWA", en: "MAMOTH — Earth Observation data-driven model for mosquito abundance; EYWA system" },
  "Aedes-AI нейрожелілері, PLoS Comput Biol": { ru: "Нейросети Aedes-AI, PLoS Comput Biol", en: "Aedes-AI neural networks, PLoS Comput Biol" },
  "Van Wagner C.E. (1987) — Canadian FWI жүйесі (spin-up тәсілінің үлгісі)": { ru: "Van Wagner C.E. (1987) — канадская система FWI (пример метода spin-up)", en: "Van Wagner C.E. (1987) — Canadian FWI system (spin-up method example)" },
  "Ақжайық Рамсар алаңы": { ru: "Рамсарские угодья Акжайык", en: "Akzhaiyk Ramsar site" },
  "Су басқан аумақ, гидропериод": { ru: "Затопленная площадь, гидропериод", en: "Flooded area, hydroperiod" },
  "🛰 өлшем": { ru: "🛰 измерение", en: "🛰 measurement" },
  "1–6 тәулік": { ru: "1–6 суток", en: "1–6 days" },
  "1–5 тәулік": { ru: "1–5 суток", en: "1–5 days" },
