  "ECMWF топырақ моделі": { ru: "Почвенная модель ECMWF", en: "ECMWF soil model" },
  "Қала/елді мекен тізілімі": { ru: "Реестр городов и населённых пунктов", en: "City and settlement registry" },
  "Жобаның өз тізілімі (8 елді мекен)": { ru: "Собственный реестр проекта (8 населённых пунктов)", en: "Project's own registry (8 settlements)" },
  "тізілім": { ru: "реестр", en: "registry" },
