// lib/pollutionTime.formatKz renders "14 тамыз 2026 ж., 15:00". Month names are
// kept out of UI_TR: in Russian they need the genitive inside a date only.
const KZ_MONTHS: Record<string, { ru: string; en: string }> = {
  "қаңтар": { ru: "января", en: "January" }, "ақпан": { ru: "февраля", en: "February" },
  "наурыз": { ru: "марта", en: "March" }, "сәуір": { ru: "апреля", en: "April" },
  "мамыр": { ru: "мая", en: "May" }, "маусым": { ru: "июня", en: "June" },
  "шілде": { ru: "июля", en: "July" }, "тамыз": { ru: "августа", en: "August" },
  "қыркүйек": { ru: "сентября", en: "September" }, "қазан": { ru: "октября", en: "October" },
  "қараша": { ru: "ноября", en: "November" }, "желтоқсан": { ru: "декабря", en: "December" },
};
function translateKzDate(s: string, lang: "ru" | "en"): string | null {
  const m = s.match(/^(\d{1,2}) (\S+) (\d{4}) ж\., (\d{2}):00$/);
  const month = m ? KZ_MONTHS[m[2]] : undefined;
  if (!m || !month) return null;
  return lang === "ru" ? `${m[1]} ${month.ru} ${m[3]} г., ${m[4]}:00` : `${m[1]} ${month.en} ${m[3]}, ${m[4]}:00`;
}

