export function translate(s: string, lang: "kk" | "ru" | "en"): string {
  if (lang === "kk") return s;
  if (UI_TR[s]?.[lang]) return UI_TR[s][lang];
  const date = translateKzDate(s, lang);
  if (date) return date;
  for (const [pattern, key] of SERVER_MESSAGE_TEMPLATES) {
    const match = s.match(pattern);
    // `{value}` is the first group; `{n}` is group n. Each group is translated
    // recursively (it is always shorter than `s`), unknown text stays as is.
    if (match) return UI_TR[key][lang].replace(/\{(value|\d+)\}/g, (_, n: string) =>
      translate(match[n === "value" ? 1 : Number(n)] ?? "", lang));
  }
  return s;
}
